package catalog

import "fmt"

// Product is a sellable item in the catalog.
type Product struct {
	SKU        string
	Name       string
	PriceCents int64
}

// Catalog holds products keyed by SKU.
type Catalog struct {
	products map[string]Product
}

// New returns an empty Catalog.
func New() *Catalog {
	return &Catalog{products: map[string]Product{}}
}

// Add puts product into the catalog, replacing any product with the same SKU.
func (c *Catalog) Add(product Product) {
	c.products[product.SKU] = product
}

// FetchProduct returns the product for sku.
func (c *Catalog) FetchProduct(sku string) (Product, error) {
	product, ok := c.products[sku]
	if !ok {
		return Product{}, fmt.Errorf("catalog: fetch product %q: not in catalog", sku)
	}
	return product, nil
}

// FetchPrice returns the price in cents for sku.
func (c *Catalog) FetchPrice(sku string) (int64, error) {
	product, err := c.FetchProduct(sku)
	if err != nil {
		return 0, err
	}
	return product.PriceCents, nil
}
